import { writeFile } from 'node:fs/promises';
import { conicalStudCut, conicalStudParameters } from '../src/simulation/conical-stud-geometry.js';
const cut = conicalStudCut(conicalStudParameters, { regenerate: true });
await writeFile(new URL('../src/data/conical-stud-profile.js', import.meta.url),
  '// Generated by scripts/bake-conical-stud-profile.mjs. Contact validation is incomplete.\n'
  + `export const conicalStudCut = ${JSON.stringify(cut)};\n`);
console.log('Saved the conical stud clearance cut. Continuous contact remains unverified.');
